pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));
        // Ensure contract has some balance to observe the effect
        vm.deal(address(this), 1 ether);
        vm.prank(address(this));
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);

        // Record balance before the call
        uint256 balanceBefore = address(c).balance;
        bool ok;
        vm.prank(nonOwner);
        try c.withdrawAll() { ok = true; } catch { ok = false; }
        uint256 balanceAfter = address(c).balance;

        // Rule: if the caller is not the owner, withdrawAll must revert and balance unchanged.
        // Here nonOwner is guaranteed not to be the original deployer (owner is msg.sender in setUp = this test contract)
        // But the test contract is address(this), which is the owner. nonOwner != address(this) so nonOwner is not owner.
        assertTrue(!ok && balanceAfter == balanceBefore);
    }
}

