pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, uint256 fundAmount) public {
        // Ensure admissible domain: fund the contract with some Ether so a drain is observable
        fundAmount = bound(fundAmount, 1, 100 ether);
        vm.assume(caller != c.owner());

        // Fund the contract using a pranked external account
        address funder = address(0x1234);
        vm.deal(funder, fundAmount);
        vm.prank(funder);
        (bool sent,) = address(c).call{value: fundAmount}("");
        require(sent, "fund failed");

        uint256 balanceBefore = address(c).balance;
        bool didNotRevert;

        // Call withdrawAll as the fuzzed non-owner caller
        vm.prank(caller);
        try c.withdrawAll() {
            didNotRevert = true;
        } catch {
            didNotRevert = false;
        }

        uint256 balanceAfter = address(c).balance;

        // Rule: if withdrawAll did NOT revert, the contract balance must be 0.
        // Reference: always reverts for non-owner, so didNotRevert is false -> rule vacuously true.
        // Mutant: non-owner call succeeds, didNotRevert is true and balanceAfter becomes 0.
        assertTrue(!didNotRevert || balanceAfter == 0);
    }
}

