pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address nonOwner = address(0x1234);

    function setUp() public {
        c = new C();
        vm.deal(nonOwner, 100 ether);
        vm.deal(address(c), 0);
    }

    function testFuzz_property(uint256 sendValue, uint256 withdrawValue) public {
        // Admissible domain: sendValue must be <= nonOwner's balance
        // and withdrawValue must be > 0 to test a withdrawal attempt.
        // Keep it wide to let the fuzzer explore.
        vm.assume(sendValue <= 100 ether);
        vm.assume(withdrawValue > 0);
        vm.assume(withdrawValue <= sendValue);

        // Reset contract state by re-deploying to ensure clean balance each run.
        c = new C();
        vm.deal(address(c), 0 ether);

        // Owner sends money to the contract via sendMoney(dest=address(c), value).
        // This increases c's balance through the fallback.
        vm.prank(c.owner());
        c.sendMoney(address(c), sendValue);

        // Now a non-owner attempts to withdraw.
        // Capture success of the call.
        bool withdrawSucceeded;
        vm.prank(nonOwner);
        try c.withdraw(withdrawValue) {
            withdrawSucceeded = true;
        } catch {
            withdrawSucceeded = false;
        }

        // The rule: after sendMoney, a non-owner cannot successfully withdraw funds
        // while the contract balance is > 0. If balance is 0, it's fine (no funds to drain).
        // Reference: onlyOwner always prevents non-owner withdrawal => withdrawSucceeded == false.
        // Bug: allows non-owner to withdraw => withdrawSucceeded == true when balance > 0.
        // We assert that the non-owner never succeeds when the contract holds a positive balance.
        assertTrue(!withdrawSucceeded || address(c).balance == 0);
    }
}

