pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, uint256 sendAmount, uint256 withdrawAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(c));
        // Bound sendAmount to a reasonable range, keeping it wide
        sendAmount = bound(sendAmount, 0, 100 ether);
        // Withdraw amount must be <= contract balance after sendMoney
        // We will set it up so that the contract has sendAmount, then try to withdraw a random amount
        // To ensure the test is meaningful, we need to fund the contract first
        // Owner deposits via sendMoney to a trusted address? Actually sendMoney sends to a target, so we send to an address that can accept it
        // We can send to address(this) to keep the balance in the contract (since address(this) is a contract but can receive ether via fallback)
        // However, sendMoney sends to a target, so we need a target that accepts ether without reverting.
        // We can use address(this) which is the test contract itself, since it doesn't have a fallback, but it can receive ether via vm.deal? No, vm.deal only for EOAs.
        // To avoid complications, we send to a known EOA, but that drains the contract. To test withdraw, we need the contract to have balance.
        // We can send to address(c) itself? sendMoney expects a target address. If we send to address(c), it will call fallback which increments depositsCount but also receives ether, so contract balance stays.
        // That works: sendMoney(address(c), sendAmount) will transfer to itself (self-transfer) via low-level call, keeping the balance.
        // But that would be a self-call, which might have side effects. It's simpler to send to a sink address that accepts ether.
        // We can deploy a simple sink contract that does nothing, but we are told to avoid helpers unless adversarial.
        // However, to set up the scenario (contract having a balance after sendMoney), we can just vm.deal directly to the contract? No, we must drive through sendMoney.
        // Let's send to a trusted address that can receive. Since the fuzzer provides nonOwner, we can use that as the target if we ensure it can receive. But fuzzed addresses are EOAs with no code, so a low-level call to them always succeeds.
        // So we can sendMoney to fuzzed nonOwner address itself. That will send ether to nonOwner, but the contract's balance decreases. That defeats the purpose.
        // Wait: we need the contract to have a balance after sendMoney in order to test withdraw. But sendMoney sends funds OUT of the contract.
        // To have the contract retain balance, we must send to an address that is the contract itself or another contract that returns it. But sending to a target that accepts and keeps it doesn't retain it.
        // Actually, the scenario: after a call to sendMoney, what is the contract's balance? sendMoney reduces it by _value.
        // So to have a non-zero balance after sendMoney, we must first fund the contract. Owner can fund via fallback (depositsCount).
        // We can pre-fund the contract by sending ether via fallback (anyone can call fallback and deposit).
        // So we can: vm.deal someone, then that someone sends ether to c via fallback, then owner calls sendMoney to some target, then we attempt withdraw as nonOwner.
        // That's allowed: we can use vm.deal, vm.prank, etc., within the test to set up the state.
        // So steps:
        // 1. Fund the contract by having a donor send ether via fallback.
        //    We can use a new address to avoid owner complications.
        address donor = address(uint160(uint256(keccak256(abi.encodePacked("donor")))));
        vm.deal(donor, sendAmount + 1 ether); // ensure donor has enough
        vm.prank(donor);
        (bool successDonation,) = address(c).call{value: sendAmount}("");
        require(successDonation, "donation failed");

        // 2. Owner calls sendMoney to some target. The target can be any address that accepts ether (EOA).
        //    After this, the contract's balance will be sendAmount - _value (if _value <= sendAmount).
        //    To maximize the chance of having a balance for withdraw, we fuzz the sendAmount and the sendMoney value.
        //    We need to ensure _value <= sendAmount, otherwise sendMoney would revert.
        //    We can bound _value accordingly.
        uint256 valueToSend = bound(withdrawAmount, 0, sendAmount);
        vm.prank(c.owner());
        c.sendMoney(nonOwner, valueToSend);

        // Now the contract should have balance: sendAmount - valueToSend (assuming no gas cost issues, we ignore).
        // 3. As nonOwner, attempt to withdraw the remaining balance.
        uint256 remaining = address(c).balance;
        // We'll withdraw all remaining.
        vm.prank(nonOwner);
        bool ok = false;
        try c.withdraw(remaining) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference should revert (ok == false) because nonOwner cannot call withdraw (onlyOwner modifier).
        // The buggy version allows nonOwner to call withdraw, so ok == true.
        assertTrue(!ok);
    }
}
// No adversarial helper needed because the bug is about missing onlyOwner modifier, not about external call failure or reentrancy.
// The nonOwner is a regular EOA, and the low-level call in sendMoney to a fuzzed address (nonOwner) always succeeds because EOAs accept ether.
// The test does not need an adversarial helper.

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }
    function test(address target, uint value) public {
        require(address(this).balance >= value);
        bool sent = false;
        try c.sendMoney{value: value}(target, value) { sent = true; } catch { sent = false; }
        assert(sent == true);
    }
}

