import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address target, uint256 value) public {
        // The owner is this test contract; we operate as the owner via direct calls.
        // To test the difference between msg.sender and tx.origin, deploy a minimal
        // intermediate contract that forwards the sendMoney call.
        // The fuzzer will supply target and value; the intermediate contract is always used.
        vm.assume(target != address(c)); // avoid self-interactions for simplicity
        vm.deal(address(c), value); // ensure contract has enough balance
        Forwarder forwarder = new Forwarder();
        // The reference C checks msg.sender, which will be the Forwarder's address, not the
        // owner (this test contract). But we are the owner, so we call forwarder which
        // calls c, making msg.sender = forwarder, but tx.origin = this test contract.
        // Under the reference, the call should revert because msg.sender != owner.
        // Under the buggy version, the call should succeed because tx.origin == owner.
        // We assert that the call reverts for the reference (proper owner check).
        // If the call succeeds, the buggy version would have allowed it.
        bool ok;
        try forwarder.forwardSendMoney(address(c), target, value) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract properly checks msg.sender and should revert (ok == false).
        // The buggy contract uses tx.origin and should not revert (ok == true).
        // Our test must distinguish them; we assert that the call does NOT revert if and only if
        // the bug is present. Since the reference MUST revert, we expect ok == false.
        assertTrue(!ok);
    }
}

contract Forwarder {
    function forwardSendMoney(address cAddr, address target, uint256 value) public {
        C(cAddr).sendMoney(target, value);
    }
}

