pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 sendValue) public {
        // Bind amounts to ensure contract has sufficient balance
        amount = bound(amount, 0, 1e36);
        sendValue = bound(sendValue, 0, 1e36);
        address owner = c.owner();
        address intermediary = address(new Forwarder(c));

        // Give the contract some ETH
        vm.deal(address(this), amount);
        vm.prank(address(this));
        (bool success,) = address(c).call{value: amount}("");
        require(success, "Initial funding failed");

        // Record owner's balance before
        uint256 ownerBalanceBefore = owner.balance;

        // Owner calls sendMoney via intermediary contract
        vm.prank(owner);
        Forwarder(intermediary).forwardSendMoney(sendValue);

        // Assert that owner's balance did not decrease unexpectedly
        // The invariant: owner's balance remains >= balanceBefore - sendValue only for the reference.
        // The buggy version (tx.origin check) allows this call to succeed with intermediary,
        // while the reference (msg.sender) reverts the attempt, preserving owner's balance.
        // We use view function on c to read public state indirectly.
        uint256 ownerBalanceAfter = owner.balance;
        assertTrue(ownerBalanceAfter >= ownerBalanceBefore - sendValue);
    }
}

contract Forwarder {
    C public immutable target;
    constructor(C _target) { target = _target; }
    function forwardSendMoney(uint256 _value) external {
        target.sendMoney(address(this), _value);
    }
    receive() external payable {}
}

