import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 value, address ownerAddr, uint256 prankSeed) public {
        vm.assume(ownerAddr != address(0));
        vm.assume(prankSeed > 0);
        address intermediate = address(new Forwarder(c));
        vm.deal(ownerAddr, value);
        vm.prank(ownerAddr);
        // Give ownership to ownerAddr, transferring ownership from msg.sender (this test contract)
        // First, ownerAddr must be the owner. We prank as current owner and transfer.
        c.transferOwnership(ownerAddr);
        vm.stopPrank();
        vm.deal(address(c), value);
        vm.prank(ownerAddr);
        (bool success, ) = intermediate.call(abi.encodeWithSelector(Forwarder.forwardSendMoney.selector, value));
        bool refOk = success;
        assertTrue(refOk);
    }
}

contract Forwarder {
    C public target;
    constructor(C _target) { target = _target; }
    function forwardSendMoney(uint256 _value) external {
        // Route the call through this intermediate; msg.sender is the Forwarder, tx.origin is the EOA that called forwardSendMoney
        target.sendMoney{value: _value}(address(this), _value);
    }
    receive() external payable {}
}

