import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        // 1. Keep amount admissible: >0 and <= contract balance after funding
        vm.assume(actor != address(0) && actor != address(this) && actor != address(c));
        vm.assume(amount > 0);
        // Fund the contract with at least 'amount' ether so withdraw succeeds
        vm.deal(address(this), amount);
        (bool funded,) = address(c).call{value: amount}("");
        require(funded, "funding failed");

        // 2. Set up an adversarial callee that reverts on transfer to show the bug affects owner, not caller.
        //    The rule is about owner balance immutability, so we directly test the invariant.
        // Record balances before
        uint256 ownerBalanceBefore = c.owner().balance;
        uint256 callerBalanceBefore = actor.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Call withdraw as 'actor'
        vm.prank(actor);
        c.withdraw(amount);

        // 3. Assert: The owner's balance remains unchanged (reference satisfies this; buggy version decreases owner balance)
        assertTrue(c.owner().balance == ownerBalanceBefore);
    }
}

