pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address delegatedCaller) public {
        // Restrict amount to be at most the contract balance we will give
        vm.assume(amount > 0);
        vm.assume(delegatedCaller != address(0));
        vm.assume(delegatedCaller != c.owner());

        // Fund the contract
        vm.deal(address(c), amount);

        // The owner delegates the call to delegatedCaller via a low-level call through a helper
        // We need the withdraw to be called by delegatedCaller but with owner's authority.
        // We achieve this by creating a helper that the owner calls, which in turn calls withdraw.
        // The helper simply forwards the call. The owner pranks the helper.
        Forwarder helper = new Forwarder();
        vm.prank(c.owner());
        helper.forward(address(c), amount);

        // After the call, the contract balance must be 0 because the funds are withdrawn to the helper (msg.sender is helper)
        // In the buggy version, the owner storage variable receives the funds, so contract balance remains amount.
        assertEq(address(c).balance, 0, "Contract balance should be 0 after withdraw");
    }
}

contract Forwarder {
    function forward(address payable target, uint256 amount) external payable {
        C(target).withdraw(amount);
    }
}

