pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Restrict amount to be withdrawable: must not exceed the balance we will deposit.
        // We'll deposit 100 ether, so bound to (0, 100 ether].
        vm.assume(amount > 0);
        bound(amount, 1, 100 ether);

        // Fund the contract with 100 ether.
        vm.deal(address(c), 100 ether);

        // Record balance before.
        uint256 balanceBefore = address(c).balance;

        // Owner attempts to withdraw.
        vm.prank(c.owner());
        (bool ok,) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", amount));

        // The reference C always reverts on failure (insufficient balance or any other revert reason).
        // The buggy version may return true without sending Ether when send fails silently.
        // Rule: if the withdraw call does not revert (ok == true), then the contract balance
        // MUST have decreased by exactly `amount`. In the buggy version, `send` can return false,
        // making the call succeed (ok == true) without transferring Ether, violating this rule.
        if (ok) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceBefore - balanceAfter == amount);
        } else {
            // Revert is acceptable behavior.
            assertTrue(true);
        }
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) public { c = _c; }

    function test(address _target, uint _value) public {
        require(address(this).balance >= _value);
        uint balBefore = _target.balance;
        bool success;
        try c.sendMoney{value: _value}(_target, _value) { success = true; } catch { success = false; }
        uint balAfter = _target.balance;
        assert(success ? balAfter == balBefore + _value : balAfter == balBefore);
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address _target, uint _value) public payable {
        require(true);
